def carry_over_refunds(apps, schema_editor):
    """Record past refunds and reopen partially refunded payments."""
    Payout = apps.get_model("core", "Payout")
    PayoutRefund = apps.get_model("core", "PayoutRefund")
    refunded = Payout.objects.filter(is_refunded=True)
    for payout in refunded.exclude(stripe_refund_id__isnull=True).exclude(stripe_refund_id=""):
        PayoutRefund.objects.get_or_create(
            stripe_refund_id=payout.stripe_refund_id,
            defaults={
                "payout": payout, "amount": payout.refunded_amount or payout.amount,
                "reason": payout.refund_reason or "", "status": "SUCCEEDED",
                "processed_at": payout.refunded_at,
            },
        )
    refunded.filter(refunded_amount__lt=F("amount")).update(
        is_refunded=False, status="PARTIALLY_REFUNDED",
    )


